Just remember the "interesting" part of the previous line and add it when the line begins with "AA ", "BB " or "MTD" (in the last case, only the short portion of the string is replaced):

#!/usr/bin/perl
use warnings;
use strict;

my @repeat;
while (my $line = <>) {
    chomp $line;
    if (my ($first, $second) = $line =~ /^MTD.{8}(...)(.*?) /) {
        $repeat[0] //= $first;
        $repeat[1] = $second;
        substr $line, 11, 3, $repeat[0];
    }
    if ($line =~ /^([AB])\1 /) {
        substr $line, 11, 0, $repeat[0] . $repeat[1];
    }
    print "$line\n";
}

